import {readFileSync,writeFileSync,existsSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {spawnSync,execFileSync} from 'node:child_process';
import {createRequire,Module} from 'node:module';
import {resolve} from 'node:path';
import os from 'node:os';
const sha = x => createHash('sha256').update(x).digest('hex');
const root=process.cwd(), self=resolve('.artifacts/measure-n01.mjs');
const recipes={bearer:['Bearer ','A',''],path:['x','/a',''],id:['id=','a',''],trace:['trace=','a',''],hex:['','a',''],hexWordMiss:['','a','g'],hexNonword:['','a','!'],idDots:['id=','.',''],traceDots:['trace=','.',''],digits:['','1','a'],decimal:['1.','1','a'],word:['','Zz0_',''],pathMiss:['x','/a','!']};
function input(name,n){const [prefix,unit,tail]=recipes[name], count=Math.floor((n-prefix.length-tail.length)/unit.length);return ' '.repeat(n-prefix.length-tail.length-count*unit.length)+prefix+unit.repeat(count)+tail;}
if(process.argv[2]==='child'){
 const name=process.argv[3],n=Number(process.argv[4]);
 const path=resolve('src/core/policy.ts'), source=readFileSync(path,'utf8');
 const require=createRequire(import.meta.url),ts=require('typescript');
 const mod=new Module(path);mod.filename=path;mod.paths=Module._nodeModulePaths(root);
 mod._compile(ts.transpileModule(source,{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2022}}).outputText,path);
 const content=input(name,n);if(content.length!==n||Buffer.byteLength(content)!==n)throw Error('size mismatch');
 mod.exports.classifyContext(input(name,100));
 const start=process.hrtime.bigint();let outcome;
 try{outcome={status:'returned',value:mod.exports.classifyContext(content)};}catch(e){outcome={status:'threw',error:{name:e.name,message:e.message}};}
 console.log(JSON.stringify({name,n,sourceSha256:sha(source),elapsedNs:Number(process.hrtime.bigint()-start),...outcome}));
}else{
 const source=readFileSync('src/core/policy.ts'),timestamp=new Date().toISOString().replaceAll(':','-');
 const out=resolve('docs/research/evidence/n01',`implementation-large-${timestamp}.json`);
 if(existsSync(out))throw Error('refuse overwrite');
 const report={measuredAt:new Date().toISOString(),environment:{node:process.version,v8:process.versions.v8,os:os.platform(),release:os.release(),cpu:os.cpus()[0].model},source:{sha256:sha(source),oracleSha256:sha(readFileSync('tests/helpers/policy-baseline.ts')),gitHead:execFileSync('git',['rev-parse','HEAD'],{windowsHide:true,encoding:'utf8'}).trim()},runner:{source:readFileSync(self,'utf8'),sha256:sha(readFileSync(self))},recipes,method:{sizes:[6000000,10485760,20971520],samples:5,childDeadlineMs:20000,warmup:100,sequential:true},results:[]};
 for(const name of Object.keys(recipes))for(const size of report.method.sizes)for(let sample=0;sample<5;sample++){
  const started=performance.now(),r=spawnSync(process.execPath,[self,'child',name,String(size)],{cwd:root,windowsHide:true,timeout:20000,encoding:'utf8',maxBuffer:1024*1024});
  let value;if(r.error?.code==='ETIMEDOUT')value={status:'timeout-censored'};else if(r.status!==0)value={status:'infrastructure-error',error:r.error?.message??r.stderr};else{value=JSON.parse(r.stdout);if(value.sourceSha256!==report.source.sha256)throw Error('source changed during measurement');}
  report.results.push({name,size,sample,wallMs:performance.now()-started,...value});writeFileSync(out,JSON.stringify(report,null,2)+'\n');
  if(sample===4)console.log(`${name} ${size}: ${value.status}`);
 }
 console.log(out);
}
